import { describe, expect, it } from "vitest"
import { formatMoney, sumMoney } from "./money.tsx"

describe("sumMoney", () => {
  it("adds exactly, where a float would not", () => {
    expect(sumMoney([{ amount: "0.1", currency: "BRL" }, { amount: "0.2", currency: "BRL" }])).toEqual([{ amount: "0.3", currency: "BRL" }])
  })
  it("keeps amounts past a float's precision", () => {
    expect(sumMoney([{ amount: "99999999999999.9999", currency: "USD" }, { amount: "0.0001", currency: "USD" }])).toEqual([
      { amount: "100000000000000", currency: "USD" },
    ])
  })
  it("never adds two currencies up", () => {
    expect(sumMoney([{ amount: "10", currency: "BRL" }, { amount: "5", currency: "USD" }, { amount: "-2.5", currency: "BRL" }])).toEqual([
      { amount: "7.5", currency: "BRL" },
      { amount: "5", currency: "USD" },
    ])
  })
})

describe("formatMoney", () => {
  it("shows the currency's places, and finer ones an amount has", () => {
    expect(formatMoney({ amount: "199", currency: "USD" })).toMatch(/199[.,]00/)
    expect(formatMoney({ amount: "12.3456", currency: "USD" })).toMatch(/12[.,]3456/)
    expect(formatMoney({ amount: "1000", currency: "JPY" })).not.toMatch(/[.,]00$/)
  })
  it("shows nothing for what is not money", () => {
    expect(formatMoney(null)).toBe("—")
  })
})
